import re

def main():
    n = int(input())
    counts = {}
    for _ in range(n):
        line = input()
        m = re.search(r"(\d{1,3}(?:\.\d{1,3}){3})", line)
        ip = m.group(1)
        counts[ip] = counts.get(ip, 0) + 1
    for ip in sorted(counts):
        print(f"{ip} {counts[ip]}")

main()

