import re

def main():
    n = int(input())
    for _ in range(n):
        line = input()
        rule, value = line.split(" ", 1)
        if rule == "EMAIL":
            ok = re.fullmatch(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", value)
        elif rule == "PHONE":
            ok = re.fullmatch(r"[6-9]\d{9}", value)
        else:
            ok = re.fullmatch(r"[A-Z]{2}[0-9]{4}", value)
        print(bool(ok))

main()
